// Cyberpunk Realism: inspect retained state without a suspended-system
    // getter substituting zero. Existing unlocalized injuries are not erased.
    public final func CRIsClearForHandover() -> Bool {
        return IsDefined(this.player) && this.currentConditionLevel == 0u && this.accumulatedPercentTowardNextLevel == 0.0 && !StatusEffectSystem.ObjectHasStatusEffectWithTag(this.player, n"DarkFutureConditionInjury");
    }

    public final func AccumulateHealthLoss(change: Float) -> Void {
        if CRBodyRuntime.Get().OwnsLocalizedInjuries() {
            return;
        }

public final func GetConditionCureItemTag() -> CName {
        if CRBodyRuntime.Get().OwnsLocalizedInjuries() {
            return n"";
        }
